/* Left navigation keeps the workspace clear and remains scrollable on short windows. */
#shell[data-navigation="dock"] { --bk-dock-reserve: 0px !important; --theme-rail-width: 184px; }
html #shell[data-navigation="dock"] #main { padding-bottom: 0 !important; padding-left: calc(var(--theme-rail-width) + 16px); }
html #shell[data-navigation="dock"]:has([data-part="shell.nav"][data-collapsed="true"]) #main { padding-left: 20px; }
[data-part="shell.nav"] > nav { left: 8px !important; top: 8px; bottom: 8px !important; transform: none !important; width: var(--theme-rail-width) !important; max-width: none !important; height: auto; flex-direction: column; justify-content: flex-start; align-items: stretch; overflow-x: hidden; overflow-y: auto; padding: 8px !important; gap: 4px !important; }
[data-part="shell.nav"] nav [data-part="shell.nav.tile"], [data-part="shell.nav"] nav [data-part="shell.nav.overlay"] { width: 100% !important; min-height: 40px !important; flex-direction: row !important; justify-content: flex-start !important; align-items: center !important; padding: 8px 10px !important; gap: 10px !important; }
[data-part="shell.nav"] nav [data-control="tile"] > span:last-child { display: block !important; font-size: 12px !important; line-height: 18px !important; white-space: normal; text-align: left; }
[data-part="shell.nav"] nav > span[aria-hidden="true"] { width: 100%; height: 1px; min-height: 1px; margin: 4px 0; }
[data-part="shell.nav.toggle"] { flex: none; align-self: center; }
[data-part="shell.nav.toggle"] svg { transform: rotate(90deg); }
[data-part="shell.nav"][data-collapsed="true"] > nav { transform: translateX(calc(-100% - 16px)) !important; }
[data-part="shell.nav"] > [data-part="shell.nav.handle"] { left: 0 !important; top: 50%; bottom: auto !important; width: 16px !important; height: 56px; padding: 10px 6px !important; border-radius: 0 !important; transform: translateX(-120%) !important; }
[data-part="shell.nav"] > [data-part="shell.nav.handle"] > span { width: 4px !important; height: 32px !important; }
[data-part="shell.nav"][data-collapsed="true"] > [data-part="shell.nav.handle"] { transform: none !important; }
@container (max-width: 760px) {
  [data-part="shell.nav"] > nav { width: 60px !important; }
  html #shell[data-navigation="dock"] #main { padding-left: 76px; }
  [data-part="shell.nav"] nav [data-part="shell.nav.tile"], [data-part="shell.nav"] nav [data-part="shell.nav.overlay"] { justify-content: center !important; padding: 8px !important; }
  [data-part="shell.nav"] nav [data-control="tile"] > span:last-child { display: none !important; }
}
